use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let intervals = input.as_array().unwrap();
    let mut sorted_intervals = intervals.into_iter().map(|v| {
        let start = v[0].as_i64().unwrap() as usize;
        let end = v[1].as_i64().unwrap() as usize;
        (start, end)
    }).collect();

    sorted_intervals.sort_unstable_by(|a, b| a.0.cmp(&b.0));

    let mut result = vec![(sorted_intervals[0].0, sorted_intervals[0].1)];
    for i in 1..sorted_intervals.len() {
        if sorted_intervals[i].0 <= result.last().unwrap().1 {
            result.last().unwrap().1 = sorted_intervals[i].1;
        } else {
            result.push(sorted_intervals[i]);
        }
    }

    Value::Array(result.into_iter().map(|v| Value::Number(v.0 as f64)).collect())
}
